with cleaned as (select *, round(quantity * 100, 2) as quantity_adjusted from inventory where last_restock > date '2023-03-27') select store_id, min(quantity_adjusted) as min_quantity_adjusted, min(quantity) as min_quantity, count(*) as event_count, approx_percentile(quantity_adjusted, 0.9) as quantity_adjusted_p90 from cleaned group by store_id having min_quantity > 0 order by event_count desc;
